const apiUrl = String.fromEnvironment('API_URL', defaultValue: 'http://localhost:8080/api');
const green = Color(0xFF2E7D32);
class ApiService { ApiService._(); static final instance=ApiService._(); String get base=>apiUrl.replaceFirst(RegExp(r'/$'),''); Future<dynamic> request(String path,{String method='GET',Map<String,dynamic>? body,bool retry=true}) async {final p=await SharedPreferences.getInstance();final token=p.getString('accessToken');final h=<String,String>{'Accept':'application/json',if(body!=null)'Content-Type':'application/json',if(token?.isNotEmpty==true)'Authorization':'Bearer $token'};final u=Uri.parse('$base$path');final b=body==null?null:jsonEncode(body);late http.Response r;switch(method){case 'POST':r=await http.post(u,headers:h,body:b);break;case 'PUT':r=await http.put(u,headers:h,body:b);break;case 'DELETE':r=await http.delete(u,headers:h);break;default:r=await http.get(u,headers:h);}if(r.statusCode==401&&retry&&!path.startsWith('/auth/')){if(await refresh())return request(path,method:method,body:body,retry:false);}dynamic d;try{d=r.body.isEmpty?null:jsonDecode(r.body);}catch(_){d=null;}if(r.statusCode<200||r.statusCode>=300){final m=d is Map?(d['message']??d['error']??'Request failed (${r.statusCode})'):'Request failed (${r.statusCode})';throw Exception(m.toString());}return d is Map&&d['data']!=null?d['data']:d;}
Future<bool> refresh() async {final p=await SharedPreferences.getInstance();final t=p.getString('refreshToken');if(t==null||t.isEmpty)return false;try{final r=await http.post(Uri.parse('$base/auth/refresh'),headers:{'Accept':'application/json','Content-Type':'application/json'},body:jsonEncode({'refreshToken':t}));if(r.statusCode<200||r.statusCode>=300)throw Exception();final raw=jsonDecode(r.body);final d=raw is Map&&raw['data'] is Map?raw['data']:raw;if(d is! Map||d['accessToken']==null)throw Exception();await p.setString('accessToken','${d['accessToken']}');if(d['refreshToken']!=null)await p.setString('refreshToken','${d['refreshToken']}');if(d['role']!=null)await p.setString('role','${d['role']}');return true;}catch(_){await logout();return false;}}
Future<Map<String,dynamic>> login(String college,String username,String password) async {final raw=await request('/auth/login',method:'POST',retry:false,body:{'collegeCode':college,'username':username,'password':password});final d=raw is Map?Map<String,dynamic>.from(raw):<String,dynamic>{};final p=await SharedPreferences.getInstance();await p.setString('accessToken','${d['accessToken']??''}');await p.setString('refreshToken','${d['refreshToken']??''}');await p.setString('username','${d['username']??username}');await p.setString('role','${d['role']??''}');return d;}
Future<void> logout() async {final p=await SharedPreferences.getInstance();await p.remove('accessToken');await p.remove('refreshToken');await p.remove('role');await p.remove('username');}
Future<Map<String,dynamic>> map(String path) async {final v=await request(path);return v is Map?Map<String,dynamic>.from(v):{};} Future<List<Map<String,dynamic>>> list(String path) async {final v=await request(path);return v is List?v.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList():[];} Future<Map<String,dynamic>> mapPost(String path,Map<String,dynamic> b) async {final v=await request(path,method:'POST',body:b);return v is Map?Map<String,dynamic>.from(v):{};} Future<Map<String,dynamic>> mapPut(String path,Map<String,dynamic> b) async {final v=await request(path,method:'PUT',body:b);return v is Map?Map<String,dynamic>.from(v):{};}
Future<Map<String,dynamic>> studentDashboard()=>map('/student/dashboard');Future<Map<String,dynamic>> teacherDashboard()=>map('/teacher/dashboard');Future<List<Map<String,dynamic>>> teacherStudents()=>list('/teacher/students');Future<List<Map<String,dynamic>>> attendance()=>list('/attendance');Future<Map<String,dynamic>> attendanceSummary()=>map('/attendance/me/summary');Future<List<Map<String,dynamic>>> studentEnrollments()=>list('/student/enrollments');Future<List<Map<String,dynamic>>> studentAssignments()=>list('/student/assignments');Future<Map<String,dynamic>> studentResults()=>map('/student/results');Future<Map<String,dynamic>> studentTimetable()=>map('/student/timetable');Future<List<Map<String,dynamic>>> teacherAssignments()=>list('/teacher/assignments');Future<List<Map<String,dynamic>>> myTimetable()=>list('/timetable/mine');Future<Map<String,dynamic>> createAttendance(Map<String,dynamic> b)=>mapPost('/attendance',b);Future<Map<String,dynamic>> updateAttendance(int id,Map<String,dynamic> b)=>mapPut('/attendance/$id',b);}
