class RootScreen extends StatefulWidget{const RootScreen({super.key});@override State<RootScreen> createState()=>_RootState();}class _RootState extends State<RootScreen>{String? role;bool loading=true;@override void initState(){super.initState();restore();}Future<void> restore()async{final p=await SharedPreferences.getInstance();final t=p.getString('accessToken');if(mounted)setState((){role=t?.isNotEmpty==true?p.getString('role'):null;loading=false;});}@override Widget build(BuildContext c){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(role==null)return LoginScreen(onLogin:(r)=>setState(()=>role=r));return HomeScreen(role:role!,onLogout:()async{await ApiService.instance.logout();if(mounted)setState(()=>role=null);});}}
class LoginScreen extends StatefulWidget{final void Function(String) onLogin;const LoginScreen({super.key,required this.onLogin});@override State<LoginScreen> createState()=>_LoginState();}class _LoginState extends State<LoginScreen>{final college=TextEditingController(),user=TextEditingController(),password=TextEditingController();bool busy=false,obscure=true;Future<void> submit()async{if([college,user,password].any((c)=>c.text.trim().isEmpty)){snack(context,'Enter all login details.');return;}setState(()=>busy=true);try{final r=await ApiService.instance.login(college.text.trim(),user.text.trim(),password.text);widget.onLogin('${r['role']??''}');}catch(e){snack(context,cleanError(e));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:480),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('EduSphere',style:TextStyle(fontSize:34,fontWeight:FontWeight.w900,color:green)),const Text('College ERP mobile',style:TextStyle(color:Colors.black54)),const SizedBox(height:34),Card(child:Padding(padding:const EdgeInsets.all(22),child:Column(children:[_field('College code',college),_field('Username',user),TextField(controller:password,obscureText:obscure,decoration:InputDecoration(labelText:'Password',suffixIcon:IconButton(onPressed:()=>setState(()=>obscure=!obscure),icon:Icon(obscure?Icons.visibility:Icons.visibility_off)))),const SizedBox(height:22),SizedBox(width:double.infinity,height:52,child:FilledButton(onPressed:busy?null:submit,child:busy?const CircularProgressIndicator(color:Colors.white):const Text('Sign in')))]))])))));Widget _field(String l,TextEditingController c)=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextField(controller:c,decoration:InputDecoration(labelText:l)));}
class HomeScreen extends StatefulWidget{final String role;final Future<void> Function() onLogout;const HomeScreen({super.key,required this.role,required this.onLogout});@override State<HomeScreen> createState()=>_HomeState();}class _HomeState extends State<HomeScreen>{Map<String,dynamic> data={};bool loading=true;bool get teacher=>widget.role.toUpperCase().contains('TEACHER');@override void initState(){super.initState();load();}Future<void> load()async{setState(()=>loading=true);try{data=await(teacher?ApiService.instance.teacherDashboard():ApiService.instance.studentDashboard());}catch(_){data={};}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext c){final name='${data['${teacher?'teacher':'student'}Name']??'User'}';final items=teacher?< _Module>[const _Module('Classes',Icons.school_outlined,TeacherClassesScreen()),const _Module('Attendance',Icons.fact_check_outlined,TeacherAttendanceScreen()),const _Module('Assignments',Icons.assignment_outlined,TeacherAssignmentsScreen()),const _Module('Timetable',Icons.calendar_month_outlined,TeacherTimetableScreen())]:< _Module>[const _Module('Classes',Icons.school_outlined,StudentClassesScreen()),const _Module('Attendance',Icons.fact_check_outlined,StudentAttendanceScreen()),const _Module('Assignments',Icons.assignment_outlined,StudentAssignmentsScreen()),const _Module('Timetable',Icons.calendar_month_outlined,StudentTimetableScreen()),const _Module('Results',Icons.bar_chart_outlined,StudentResultsScreen())];return Scaffold(appBar:AppBar(title:const Text('EduSphere',style:TextStyle(fontWeight:FontWeight.w900)),actions:[IconButton(tooltip:'Notifications',onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>const NotificationsScreen())),icon:const Icon(Icons.notifications_outlined)),IconButton(tooltip:'Profile',onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ProfileScreen(role:widget.role))),icon:const Icon(Icons.person_outline)),IconButton(onPressed:widget.onLogout,icon:const Icon(Icons.logout))]),body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(20),children:[Text(teacher?'Welcome back,':'Good to see you,',style:const TextStyle(color:Colors.black54)),Text(name,style:const TextStyle(fontSize:28,fontWeight:FontWeight.w900)),const SizedBox(height:20),if(loading)const Center(child:Padding(padding:EdgeInsets.all(30),child:CircularProgressIndicator()))else...[Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:green,borderRadius:BorderRadius.all(Radius.circular(22))),child:Text(teacher?'${data['totalSubjects']??0} subjects · ${data['totalStudents']??0} students':'${data['course']??'Student'} · Attendance ${data['attendancePercentage']??0}%',style:const TextStyle(color:Colors.white,fontSize:19,fontWeight:FontWeight.w800))),const SizedBox(height:20),const Text('Modules',style:TextStyle(fontSize:20,fontWeight:FontWeight.w900)),const SizedBox(height:8),Card(child:Column(children:items.map((m)=>ListTile(leading:CircleAvatar(backgroundColor:const Color(0xFFE8F5E9),child:Icon(m.icon,color:green)),title:Text(m.title,style:const TextStyle(fontWeight:FontWeight.w700)),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>m.page))).toList()))]]));}}
