class TeacherAttendanceScreen extends StatefulWidget{const TeacherAttendanceScreen({super.key});@override State<TeacherAttendanceScreen> createState()=>_TeacherAttendanceState();}class _TeacherAttendanceState extends State<TeacherAttendanceScreen>{List<Map<String,dynamic>> students=[],records=[];String? group;DateTime date=DateTime.now();final status=<String,String>{};bool loading=true,saving=false;String get day=>'${date.year.toString().padLeft(4,'0')}-${date.month.toString().padLeft(2,'0')}-${date.day.toString().padLeft(2,'0')}';@override void initState(){super.initState();load();}Future<void> load()async{setState(()=>loading=true);try{final r=await Future.wait([ApiService.instance.teacherStudents(),ApiService.instance.attendance()]);students=r[0] as List<Map<String,dynamic>>;records=r[1] as List<Map<String,dynamic>>;final g=groups;group=g.containsKey(group)?group:g.keys.firstOrNull;sync();}catch(e){if(mounted)snack(context,cleanError(e));}finally{if(mounted)setState(()=>loading=false);}}Map<String,List<Map<String,dynamic>>> get groups{final g=<String,List<Map<String,dynamic>>>{};for(final s in students){g.putIfAbsent('${s['classSubjectId']??''}',()=>[]).add(s);}return g;}List<Map<String,dynamic>> get selected=>group==null?[]:(groups[group]??[]);void sync(){status.clear();for(final s in selected){final id='${s['id']}';final r=records.where((x)=>'${x['classEnrollmentId']}'==id&&'${x['attendanceDate']}'==day).firstOrNull;status[id]='${r?['status']??'PRESENT'}'.toUpperCase();}}Future<void> save()async{setState(()=>saving=true);try{for(final s in selected){final eid=int.tryParse('${s['id']}');if(eid==null)continue;final p={'classEnrollmentId':eid,'attendanceDate':day,'status':status['$eid']??'PRESENT'};final old=records.where((x)=>'${x['classEnrollmentId']}'=='$eid'&&'${x['attendanceDate']}'==day).firstOrNull;if(old?['id']!=null)await ApiService.instance.updateAttendance(int.parse('${old!['id']}'),p);else await ApiService.instance.createAttendance(p);}snack(context,'Attendance saved');await load();}catch(e){snack(context,cleanError(e));}finally{if(mounted)setState(()=>saving=false);}}@override Widget build(BuildContext c){return Scaffold(appBar:AppBar(title:const Text('Mark Attendance')),body:loading?const Center(child:CircularProgressIndicator()):Column(children:[Padding(padding:const EdgeInsets.all(16),child:Column(children:[DropdownButtonFormField<String>(value:group,decoration:const InputDecoration(labelText:'Class / subject'),items:groups.entries.map((e){final f=e.value.first;return DropdownMenuItem(value:e.key,child:Text('${f['className']??'Class'} · ${f['subjectName']??'Subject'}'));}).toList(),onChanged:(v){setState((){group=v;sync();});}),ListTile(contentPadding:EdgeInsets.zero,title:Text('Date: $day'),trailing:const Icon(Icons.calendar_month),onTap:()async{final d=await showDatePicker(context:c,initialDate:date,firstDate:DateTime(2020),lastDate:DateTime(2100));if(d!=null)setState((){date=d;sync();});})])),Expanded(child:ListView.builder(padding:const EdgeInsets.fromLTRB(16,0,16,100),itemCount:selected.length,itemBuilder:(c,i){final s=selected[i],id='${s['id']}',v=status[id]??'PRESENT';return Card(child:ListTile(title:Text('${s['studentName']??'Student'}'),subtitle:Text('${s['admissionNo']??''}'),trailing:DropdownButton<String>(value:v,items:['PRESENT','ABSENT','LATE','EXCUSED'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(x)=>setState(()=>status[id]=x!))));})),]),floatingActionButton:FloatingActionButton.extended(onPressed:saving||selected.isEmpty?null:save,label:Text(saving?'Saving…':'Save')));}}
